# Use function overloading by arity
fn greet() {
    return "Hello!"
}

fn greet(name) {
    return "Hello, " + name + "!"
}

fn greet(name, greeting) {
    return greeting + ", " + name + "!"
}

print(greet())             # "Hello!"
print(greet("Alice"))      # "Hello, Alice!"
print(greet("Bob", "Hi"))  # "Hi, Bob!"

