# Use function calls directly in match arms
fn double(n) { return n * 2 }
fn square(n) { return n * n }

fn transform(op, val) {
    return match op {
        "double" => double(val),
        "square" => square(val),
        _ => val
    }
}
print(transform("double", 5))  # 10
print(transform("square", 4))  # 16

